def shade(cell, color):
    tcPr=cell._tc.get_or_add_tcPr(); shd=OxmlElement('w:shd'); shd.set(qn('w:fill'),color); tcPr.append(shd)
def set_cell_text(cell,text,bold=False,color='FFFFFF',size=9):
    p=cell.paragraphs[0]; p.paragraph_format.space_after=Pt(0); r=p.add_run(text); r.bold=bold; r.font.size=Pt(size); r.font.color.rgb=RGBColor.from_string(color)
    cell.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
def add_title(text):
    p=doc.add_paragraph(style='Title'); p.add_run(text); p.paragraph_format.space_after=Pt(6)
def add_h1(text):
    p=doc.add_paragraph(text,style='Heading 1'); p.paragraph_format.space_before=Pt(18); p.paragraph_format.space_after=Pt(7)
def add_h2(text):
    p=doc.add_paragraph(text,style='Heading 2'); p.paragraph_format.space_before=Pt(12); p.paragraph_format.space_after=Pt(4)
def para(text,bold_prefix=None):
    p=doc.add_paragraph(); p.paragraph_format.space_after=Pt(6); p.paragraph_format.line_spacing=1.12
    if bold_prefix and text.startswith(bold_prefix):
        p.add_run(bold_prefix).bold=True; p.add_run(text[len(bold_prefix):])
    else:p.add_run(text)
def bullets(items):
    for t in items:
        p=doc.add_paragraph(style='List Bullet'); p.paragraph_format.space_after=Pt(3); p.add_run(t)
def table(rows, widths=None):
    t=doc.add_table(rows=1, cols=len(rows[0])); t.alignment=WD_TABLE_ALIGNMENT.CENTER; t.style='Table Grid'
    for i,head in enumerate(rows[0]): shade(t.rows[0].cells[i],'173E47'); set_cell_text(t.rows[0].cells[i],head,True)
    for row in rows[1:]:
        cells=t.add_row().cells
        for i,val in enumerate(row):
            if len(t.rows)%2==0:shade(cells[i],'EDF5F5')
            set_cell_text(cells[i],val,False,'263038')
    if widths:
        for row in t.rows:
            for i,w in enumerate(widths):row.cells[i].width=Inches(w)
    doc.add_paragraph().paragraph_format.space_after=Pt(1)

